\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -131\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 De correctione fraterna}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >Incipit tractatus de correctione fraterna< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Circa primum notandum secundum sanctum Thomam}}\plain \f1\i\lang1033\fs24  in 4\plain \f1\i\super\lang1033\fs24 to\plain \f1\i\lang1033\fs24  dist. 19 ar. 3 in responsione 2\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24  questionis \u8230 \'85\plain \f1\lang1033\fs20 \endash \plain \f1\i\lang1033\fs24 \u8230 \'85 incidat in penam. Explicit tractatus de fraterna correctione.\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -132\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Sequitur consilium Narbonensis capituli circa correctionem fraternam< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Cum circa custodiam innocencie}}\plain \f1\i\lang1033\fs24  et fame sit nobis sollicitudo \u8230 \'85 et assensu presentibus litteris imposuerunt\plain \f1\lang1033\fs24 .}

