\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (137\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Bestellung von Inquisitoren\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Universis et singulis ad quos presentes peruenerint fr. Bartholomeus Texerii \u8230 \'85 totius ordinis predicatorum humilis magister et seruus salutem \u8230 \'85 Cum ex speciali priuilegio sedis apostolice sit mihi collata auctoritas inquisitores heretice\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 prauitatis in certis ciuitatibus , dyocesibus et prouinciis instituendi\plain \f1\lang1033\fs24  \u8230 \'85 Es folgen die diesbez\u252 \'fcglichen \plain \f1\scaps\lang1033\fs24 p\plain \f1\scaps\lang1033\fs24 \u228 \'e4\plain \f1\scaps\lang1033\fs24 pstlichen Bullen\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Bonifacius\plain \f1\lang1033\fs24  [IX.] \plain \f1\i\lang1033\fs24 episcopus \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Meritis vestre deuocionis}}\plain \f1\lang1033\fs24  \u8230 \'85\~; (137\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Gregorius\plain \f1\lang1033\fs24  [IX.] \plain \f1\i\lang1033\fs24 episcopus {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 \u8230 \'85Ab exordio nascentis ecclesie}}\plain \f1\lang1033\fs24  \u8230 \'85\plain \f1\i\lang1033\fs24 Datum Rome \u8230 \'85 pontificatus\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 nostri anno septimo\plain \f1\lang1033\fs24 ;  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (138\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) [ohne Nennung des Autors] {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Quo circa ut pestis heretica radicitus extirpetur}}\plain \f1\i\lang1033\fs24  et fides catholica fortius inualescat \u8230 \'85 Ipsum magistrum Henricum Kaltyssen quem ad predictum officium inquisitionis sufficientem et ydoneum reputo \u8230 \'85 inquisitorum heretice prauitatis auctoritate predicta \u8230 \'85 instituo \u8230 \'85 Datum Basilee die sexto mensis Marcii anno domini\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 millesimo quadringentesimo quinto\plain \f1\lang1033\fs24 . \plain \f1\lang1033\fs20 \endash \plain \f1\lang1033\fs24  Vgl. dazu Kalteisen LThK\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24  5, 193. 
