\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 124\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Passio domini Jesu Christi secundum quatuor evangelistas}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (124\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Sequitur passio domini nostri Jhesu Christi secundum Matheum etc< Et factum\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 est cum consummasset Jhesus sermones\plain \f1\lang1033\fs24  \u8230 \'85 Mt 26,1-28,20.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -133\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Sequitur passio domini nostri Jhesu Christi secundum Marcum< Erat autem\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 pascha et azima post biduum\plain \f1\lang1033\fs24  \u8230 \'85 Mc 14,1-16,20.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (133\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -138\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Sequitur passio domini nostri Jhesu Christi secundum Lucam< Appropinquabit\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 dies festus asimorum qui dicitur pascha\plain \f1\lang1033\fs24  \u8230 \'85 Lc 22,1-24,53.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (138\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Sequitur passio domini nostri Jhesu Christi secundum Johannem< Hec cum\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 dixisset Jhesus egressus est cum discipulis suis\plain \f1\lang1033\fs24  \u8230 \'85 Io 18,1-20,31.
