\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -205\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones de sanctis}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -193\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 De sancto Joanne baptista sermo< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Magnificatus est puer Samuel aput deum. I Reg. II (21). Verba ista commendant }}\plain \f1\i\lang1033\fs24 et extollunt Johannem baptistam sub figura Samuelis \u8230 \'85\plain \f1\lang1033\fs20 \endash \plain \f1\i\lang1033\fs24 \u8230 \'85 item preter premium essentiale et substantiale fuit coronatus triplici aureola scil. virginum doctorum et martirum etc. Ad quod premium eternum nos perducat Jhesus Christus meritis beati Johannis etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (194\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 De sancto Andrea apostolo< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Suspendium elegit anima mea. Job septimo (7,15). Dicit Bernhardus}}\plain \f1\i\lang1033\fs24  super cantica sermonum XXVII: Beatus qui te hominem inter homines conuersantem \u8230 \'85\plain \f1\lang1033\fs20 \endash \plain \f1\i\lang1033\fs24 \u8230 \'85 et a suo officio suspensa dirigor moueor doceor regor vita supersubstantiali cui viuo qua repleor etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -199\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 De s. Petro et Paulo apostolis< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Fac tibi duas tubas argenteas ductiles. Numeri decimo (10,2) dicit Hrabanus in glossa}}\plain \f1\lang1033\fs24  (\~?) \plain \f1\i\lang1033\fs24 tam in aduersis quam prosperis \u8230 \'85\plain \f1\lang1033\fs20 \endash \plain \f1\i\lang1033\fs24 \u8230 \'85 quacumque deus inueniatur tamen in infinitum latet. Vnde ipse dicit Hierarchie III post me ingredi non cessabis. Amen.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (199\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -202\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 De sancto Joanne ewangelista et apostolo< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Facies aquile desuper ipsorum quatuor}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 . }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ezech. 1}}\plain \f1\lang1033\fs24\chcbpat19  (10). {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gregorius Moralia XIII}}\plain \f1\i\lang1033\fs24  dicit quod per aquilam significatur \u8230 \'85\plain \f1\lang1033\fs20 \endash \plain \f1\i\lang1033\fs24 \u8230 \'85 Hec\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 vltima primam\plain \f1\lang1033\fs24  [scil. affectionem] \plain \f1\i\lang1033\fs24 eliminat\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 2\plain \f1\i\super\lang1033\fs24 am\plain \f1\i\lang1033\fs24  remunerat. Prima affectio sicut dicit Bernhardus est dulcis sed turpis etc.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (202\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -205\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 De sancta Maria Magdalena< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Surge propera amica mea formosa mea et veni. Cant. secundo (10). Sicut docet Origenes}}\plain \f1\i\lang1033\fs24  super Canticorum II cap. predicator debet esse amicus \u8230 \'85\plain \f1\lang1033\fs20 \endash \plain \f1\i\lang1033\fs24 \u8230 \'85 que postmodum cedulam accipiens de altari peccata sua deleta inuenit. Quod nobis concedat Jhesus Christus dei filius etc.
\par \pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

