\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 206\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -211\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Ps.-Bernhardus Claraevallensis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De meditatione passionis Christi per septem diei horas libellus}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >Contemplatio s. Bernhardi de passione domini< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Septies in die laudem dixi tibi (Ps 118, 164). Rogasti me }}\plain \f1\i\lang1033\fs24 \u8230 \'85\plain \f1\lang1033\fs20 \endash \plain \f1\i\lang1033\fs24  \u8230 \'85 et sedebis iuxta monumentum eius domini nostri Jhesu Christi qui viuit et regnat deus cum patre et spiritu sancto in secula seculorum. Amen.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Druck: PL 94, 561. \endash  \plain \f1\scaps\lang1033\fs20 Glorieux\plain \f1\lang1033\fs20 , Pour revaloriser Migne, S. 53.\plain \f1\lang1033\fs24  
\par \pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

