\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 211\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -215\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Ps.-Bernhardus Claraevallensis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Sermo de vita et passione domini}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >Prologus s. Bernhardi in contemplationem de passione Christi< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Jhesum Nazarenum a Judeis innocenter condemnatum}}\plain \f1\i\lang1033\fs24  a gentibus crucifixum\plain \f1\lang1033\fs24  \u8230 \'85\~; Sermo: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Ubi est glori[fic]atio tua, christiane}}\plain \f1\i\lang1033\fs24 , nisi in nomine crucifixi\plain \f1\lang1033\fs24  \u8230 \'85 Text teilweise nur auszugsweise wiedergegeben (springt z. B. von PL 184, 962 D auf 964 B). Schluss ver\u228 \'e4ndert gegen\u252 \'fcber PL: \u8230 \'85 \plain \f1\i\lang1033\fs24 ac te benedicam te deum deorum in Syon cui cum filio tuo et eodem spritu sancto vna est gloria imperium et maiestas per infinita seculorum secula. Amen.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Druck: PL 184, 953- 965 B.
\par \pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

