\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 216\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -217\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Planctus BMV}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\b\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >Bernhardus de planctu \plain \f1\lang1033\fs24 [dar\u252 \'fcber geschrieben: \plain \f1\i\lang1033\fs24 partu\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 virginis Marie< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnis qui ad hoc nomen Emanuel}}\plain \f1\i\lang1033\fs24  hoc est verbum patris altissimi quod factum est venire desiderat virginem que genuit ipsum vinculo totius caritatis astringit \u8230 \'85\plain \f1\lang1033\fs20 \endash \plain \f1\i\lang1033\fs24  \u8230 \'85 pro me fundite preces ad illos vt semper in laude eorum merear esse dignus quos laudat omnis spiritus.\plain \f1\lang1033\fs20  \endash \plain \f1\lang1033\fs24  (216\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 De partu virginis< \plain \f1\i\lang1033\fs24\chcbpat19  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Audistis filie Jerusalem que Gabriel }}\plain \f1\i\lang1033\fs24 Joseph sponso regine mundi dixit in somnis apparens \u8230 \'85\plain \f1\lang1033\fs20 \endash \plain \f1\i\lang1033\fs24  \u8230 \'85 O beati oculi quorum lacrimas deus absterget ipse saluator mundi. Amen.\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Dieser Text nachgewiesen bei L. \plain \f1\scaps\lang1033\fs20 Mezey\plain \f1\lang1033\fs20 , Catalogus manuscriptorum bibliothecae Universitatis Budapestensis. Budapest 1961, S. 210 (= Hs. 128, fol. 25).
\par \pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

