\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u220 \'dcberwiegend Bernhardzitate, vereinzelt eingestreut solche von {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Isidor}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Augustinus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Gregorius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Seneca}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[6].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Cicero}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[7].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Hieronymus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[8].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Anselm}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezper[9].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Boethius}}\plain \f1\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [B]ernhard: Quid superbis terra et cinis }}\plain \f1\i\lang1033\fs24 si\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 superbientibus angelis deus non pepercit multo minus tibi putredo et uermis\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\i\lang1033\fs24 Bernhardus:\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Qui curam uestri nobis commisistis quod rursum non de uobis introiuit\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\i\lang1033\fs24 Augustinus: Verus\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 obediens mandatum\plain \f1\lang1033\fs24  \u8230 \'85 Etc. \plain \f1\i\lang1033\fs24 Bernhardus: O ueneranda sacerdotum dignitas inter quorum manus uelut in utero uirginis dei filius incarnatur \u8230 \'85 cuius delicie sunt esse cum filiis hominum\plain \f1\lang1033\fs24 .
