\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 154\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -156\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Indulta et privilegia Ordini fratrum minorum concessa}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 Sanctissimus in Christo pater et dominus Gregorius nonus\plain \f1\lang1033\fs24  (1227-1241) \plain \f1\i\lang1033\fs24 qui beatum Franciscum, Anthonium et beatam Elizabeth ascripsit chatalogo sanctorum concessit omnibus causa\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 deuocionis visitantibus ecclesias fratrum minorum per totum\plain \f1\lang1033\fs24  \u8230 \'85; \plain \f1\i\lang1033\fs24 Item probauit stigmata beati\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Francisci et excommunicauit detrahentes eiusdem stigmatibus\plain \f1\lang1033\fs24  \u8230 \'85 Es werden aufgez\u228 \'e4hlt Indulte und Privilegien der P\u228 \'e4pste Alexander IV. (1254-61); Martin IV. (1281-85); Innocens IV. (1243-1254); Bonifaz VIII. (1294-1303); Clemens V. (1305-14); Benedikt XI. (1303-04); Nikolaus IV. (1288-92); Gregor X. (1271-76); Urban V. (1362-70); Johannes XXII (1316-34); Clemens IV. (1265-68). Letztgenanntes Schreiben Bulle von Nikolaus IV. aus Avignon 1292.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Vgl. N. \plain \f1\scaps\lang1033\fs20 Paulus\plain \f1\lang1033\fs20 , Die Abl\u228 \'e4sse des Franziskanerordens im Mittelalter, in: Franziskanische Studien 1923. - B. \plain \f1\scaps\lang1033\fs20 Mathis\plain \f1\lang1033\fs20 , Die Privilegien des Franziskanerordens. Paderborn 1928.
\par \pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

