\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Beati qui habitant in domo tua domine in secula seculorum laudabunt te. Ps (83,5). Augustinus libro soliloquiorum}}\plain \f1\i\lang1033\fs24 , c. 34 ad nostrum propositum ait\~: O regnum eternum regnum omnium\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 seculorum\plain \f1\lang1033\fs24  \u8230 \'85- (167\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 in eterna beatitudine gaudere. Quod nobis concedat qui uiuit et regnat per infinita secula seculorum. Amen.- Adhuc deficient due partes seu contemplaciones\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 huius materie etc\plain \f1\lang1033\fs24 .- (167\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 )  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Quid prodest homini si mundum vniuersum lucraretur \u8230 \'85 Mt 16 cap o [26]. Reprehensibiles sunt}}\plain \f1\i\lang1033\fs24  et habere possunt\plain \f1\lang1033\fs24  \u8230 \'85- (180\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 cum angelis videntes viuentem in\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 secula seculorum. Quod nobis concedat omnipotens pater et filius et spiritus. Amen\plain \f1\lang1033\fs24 .- (180\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Morte morieris. Gn cap. 2o (17). Estimaui sepe numero}}\plain \f1\lang1033\fs24  (\~?) \plain \f1\i\lang1033\fs24 uel tam utile anime racionali esse\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 posse ad fugam vicinorum\plain \f1\lang1033\fs24  \u8230 \'85- (188\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8230 \'85 \plain \f1\i\lang1033\fs24 post generalem resurrectionem corpus cum anima letabuntur per infinita secula seculorum. Ad quam nos perducat trinus et vnus. Amen. Finis\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 huius\plain \f1\lang1033\fs24 . Etc. (192\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Timete deum et date illi honorem quia uenit hora iudicii eius ut supra ostensum\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 est \plain \f1\lang1033\fs24 \u8230 \'85 Zum gleichen Thema folgen drei weitere Meditationen. Danach (208\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -223\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) f\u252 \'fcnf Meditationen \u252 \'fcber das Schriftwort: \plain \f1\i\lang1033\fs24 Mittite eum in tenebras exteriores\plain \f1\lang1033\fs24  (Mt 22,13). Letzte Meditatio (222\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ): \plain \f1\i\lang1033\fs24 Mittite \u8230 \'85 Nunc circa quartam penam generalem dampnatorum est insistendum que combustionis dicitur \u8230 \'85-\u8230 \'85 deinceps flammis estuant atque integri perseuerant. -\plain \f1\lang1033\fs24  224\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs24  leer.
\par \pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

