\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Prologus super antiphonam salue regina\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Quia excellencia virginis gloriose omnem ligwam (!) ymmo omnem creaturam}}\plain \f1\i\lang1033\fs24  ad sui laudem excitat et invitat\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 et hoc in processu tractatus clarius elucebit\plain \f1\lang1033\fs24 . Die \plain \f1\i\lang1033\fs24 Expositio\plain \f1\lang1033\fs24  wird im Prolog Petrus, Bischof von S. de Compostela zugeschrieben (\plain \f1\i\lang1033\fs24 super antiphonam\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 edita a petro Episcopo de Compostella, que ab ordine Cysterciensi\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 decantatur\plain \f1\lang1033\fs24 ) und gliedert sich in vier Teile. \endash  (101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Capitulum primum\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Salue regina misericordie. Hec antiphona censenda est quedam epistola}}\plain \f1\i\lang1033\fs24  tocius sancte matris ecclesie militantis\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 rogamus ergo mariam, ut post hoc exilium ostendat nobis ihesum benedictum fructum ventris sui, qui est deus benedictus in secula seculorum. Amen\plain \f1\lang1033\fs24 . \endash  (123\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Index: >\plain \f1\i\lang1033\fs24 Q\plain \f1\lang1033\fs24 <\plain \f1\i\lang1033\fs24 uia in tractatu premisso plura predicabilia reperiuntur, que ad diuersas materias vel sermones possunt applicari et introduci, que sine registro difficulter et cum tedio possent inveniri\plain \f1\lang1033\fs24  ... .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Parallelhss. (in Auswahl): Augsburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat18 Cod. II. 1.2\u176 \'b0 182}}\plain \f1\lang1033\fs20 , 1\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -36\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  (Zuschreibung an Bernoldus Caesariensis); M\u252 \'fcnchen, BSB, {\field{\*\fldinst HYPERLINK "hida://5007[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat18 Clm 28202}}\plain \f1\lang1033\fs20 , 160\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -192\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20  (Zuschreibung an Petrus de Compostela). \endash  Lit.: Zu Bernoldus Caesariensis vgl. DHGE 8, Sp. 853. \endash  LexMA 1, Sp. 2007. \endash  Rep. fontium 2, Sp. 517-518. \endash  \u178 \'b2VL 1 (1978), Sp. 798-800.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

