\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 Expositio dominice orationis secundum fratrem Thomam de Aquino\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 >P<Ater noster etc. Jnter alias orationes oratio dominica principalior inuenitur}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \endash  ... \plain \f1\i\lang1033\fs24 et huic contrariantur aduersitates et tribulationes; et ad hoc remouendum petimus:\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 sed libera nos a malo. Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
