\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 332\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -367\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Thomas Ebendorfer de Haselbach}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Sermones VII de confessione}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (332\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -336\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Sermo 1: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [E]Cce nunc tempus acceptabile, ecce nunc dies salutis (IICor 2,6). Vbi supra. Et quia presens tempus acceptabile est tempus milicie christiane}}\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quam deberet soluere in purgatorio, ut patet ex dictis\plain \f1\lang1033\fs24 . \endash  (336\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -341\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Sermo 2: >\plain \f1\i\lang1033\fs24 Sermo secundus de confessione\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [N]Egligencia ista, qua quis negligit nostre precepta dei}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et ostendens iudicatur sapiens. Sic est in proposito de peccatis\plain \f1\lang1033\fs24 . \endash  (341\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -346\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Sermo 3: >\plain \f1\i\lang1033\fs24 Sermo tercius de confessione\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 [S]Apiens dicit sapiencie xix: \u8250 \'9bQui negligit viam suam, mortificabitur\u8249 \'8b (Sap 19,16)}}\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 et Jeremie 48 dicitur: \u8250 \'9bMaledictus qui facit opus diuisis\plain \f1\lang1033\fs24  \u8230 \'85\plain \f1\i\lang1033\fs24 \u8249 \'8b\plain \f1\lang1033\fs24  (Ier 48,10). \plain \f1\i\lang1033\fs24 Ille autem precipue negligenter agit, qui facit precepta dei parua intencione \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 si culpis irrititus\plain \f1\lang1033\fs24  (vielm. irretitus) \plain \f1\i\lang1033\fs24 ad penitenciam venit\plain \f1\lang1033\fs24 . (346\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -352\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Sermo 4: >\plain \f1\i\lang1033\fs24 Sermo quartus de confessione\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [L]Icet confessio sit difficilis fieri multis, quia repugnat noster exterior homo}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 ne incidamus in manus dei viuentis, quod est horribile, ut dicit Apostolus ad hebreos 10\plain \f1\lang1033\fs24  (vgl. Hbr 10,31). \plain \f1\i\lang1033\fs24 Vt reconciliati deo in eius amore sine fine perseueremus. Amen\plain \f1\lang1033\fs24 . \endash  (352\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -359\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) Sermo 5: >\plain \f1\i\lang1033\fs24 Sermo quintus de confessione\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [M]Vlti sunt negligentes considerare vitam suam, qui soliti sunt dicere}}\plain \f1\i\lang1033\fs24 : \u8250 \'9bego libenter confiterer de omnibus peccatis meis sicud deus nouit\u8249 \'8b\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et sic confessor non suspicatur\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 de adulterio vel quod illud commiserit cum alieno\plain \f1\lang1033\fs24 . \endash  (359\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -366\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Sermo 6: >\plain \f1\i\lang1033\fs24 Sermo sextus de confessione\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [P]Ostquam homo lapsus est in peccatum mortale, debet vigilanter operari}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 occurrente oportunitate loci et temporis et confessionem habentem in talem legitimam auctoritatem\plain \f1\lang1033\fs24 . (366\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -367\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Sermo 7: >\plain \f1\i\lang1033\fs24 Sermo septimus de confessione\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 >I<N omibus nostris operacionibus, locucionibus, verbis et cogitacionibus}}\plain \f1\i\lang1033\fs24  seruandus est debitus modus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 confugere debemus ad cofessionem, dicendum erit per graciam dicamus \u8250 \'9bAue Maria etc\u8249 \'8b\plain \f1\lang1033\fs24 . (Textabbruch: Predigt endet mit dem Prothema). \endash  367\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -370\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Parallelhs.: Kremsm\u252 \'fcnster, Stiftsbibl., CC 22, 41\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -98\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 . \endash  \plain \f1\lang1033\fs20\cf1 Lit.: \plain \f1\scaps\lang1033\fs20\cf1 Lhotsky\plain \f1\lang1033\fs20\cf1 , S. 82 f., Nr. 101.
