\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 185\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -186d\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 De vitiis et virtutibus}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (185\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -185\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Assit in principio sancta maria meo\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [D]eclina a malo et fac bonum, perquire pacem et persequere eam (Ps 33, 15). Perfeccio humane justitie in tribus consistit}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et propter hoc dicit: inquire pacem et persequere eam, id est perseueranter quere uel sequere\plain \f1\lang1033\fs24 . Aldobrandinus Cavalcanti, Sermo in visitatione domus religiosae. \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Repertorium 1, S. 181, Nr. 436 (C19). \endash  (185\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -185a\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Quid est uicium\plain \f1\lang1033\fs24 <. \plain \f1\i\lang1033\fs24 Nota, {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 vicium est actus interior uel exterior debito fine priuatus}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quia virtutes devictis tamen principalibus omnes quiescunt et perpetua uoce delentur\plain \f1\lang1033\fs24 . \endash  (185a\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -185a\plain \f1\super\lang1033\fs24 va\plain \f1\i\lang1033\fs24 ) Sequitur de virtute\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 >[V]irtus secundum beatum< Augustinum in libro \u8250 \'9bDe libero arbitrio\u8249 \'8b est bona qualitas mentis}}\plain \f1\i\lang1033\fs24 , qua recte uiuitur, qua nemo male vtitur, quam deus in nobis sine nobis operatur\plain \f1\lang1033\fs24  (vgl. Petrus Lombardus, Sententiae, li. 2, dist. 27, ed. PL 192, 714A) \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 per virtutem animi constancia fidei seu operum bonorum perseuerancium pulsat et pullulat\plain \f1\lang1033\fs24 . \endash  (185a\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -186\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Quid est vicium\plain \f1\lang1033\fs24 <. \plain \f1\i\lang1033\fs24 Vicium est actus interior uel exterior\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 vt gregorius super exodum ait. Et sunt hec: Inanis gloria, ira, invidia, auaricia, castrimargia\plain \f1\lang1033\fs24  (!), \plain \f1\i\lang1033\fs24 luxuria, accidia\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 obstinacio est pertinacia, dolus est fraudulentia in malo deceptacione\plain \f1\lang1033\fs24 . Vgl. auch 185\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -185a\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 . \endash  186\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -186d\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer. 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

