\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 187\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -193\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Sermo in die animarum}}\plain \f1\b\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Sermones in festivitatibus BMV}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (187\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -187\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Sermo 1: >\plain \f1\i\lang1033\fs24 Sermo bonus in die animarum per johannem n\u252 \'fcssel\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Gaudete cum gaudentibus, flete cum flentibus (vgl. Rm 12,15). Duo festa pariter agit duo magna festa pariter peragit}}\plain \f1\i\lang1033\fs24 , scilicet festum omnium sanctorum et festum mortuorum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 penitencia iam peracta vidit eam de purgatorio egredientem et celum ascendentem\plain \f1\lang1033\fs24 . \endash  (188\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -190\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Sermo 2: >\plain \f1\i\lang1033\fs24 Sermo de assumptione beate virginis scriptus per johannem n\u252 \'fcssel tunc plebanum et canonicum\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 1439\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 \u8250 \'9bIntrauit ihesus in quoddam castellum\u8249 \'8b usque huc \u8250 \'9bporro unum est necessarium\u8249 \'8b}}\plain \f1\lang1033\fs24\chcbpat17  (Lc 10, 38-42). {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Pro quo sciendum dicit \u8250 \'9bunum est necessarium\u8249 \'8b}}\plain \f1\i\lang1033\fs24 , quod est diligere deum pre omnibus negociis secularibus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 ordinavit sibi tale castellum, de quo uerba thematis sonant, scilicet \u8250 \'9bintrauit ihesus in quoddam castellum\u8249 \'8b, id est beatam virginem prenunciare debemus\plain \f1\lang1033\fs24 . \endash  Schlussschrift: \plain \f1\i\lang1033\fs24 Johannes n\u252 \'fcssel canonicus et plebanus 1440. Orate pro eo beatam virginem mariam\plain \f1\lang1033\fs24 . \endash  (190\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -192\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Sermo 3: \plain \f1\i\lang1033\fs24 Sequitur sermo denuntiate\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 beate marie\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [L]iber generacionis ihesu christi filii dauid (Mt 1,1). Hodie enim celebrat ecclesia [sc. festum annuntiationis] virginis gloriose}}\plain \f1\i\lang1033\fs24  et hec propter tria \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 deus pater omnipotens adhibuit diligenciam, ut illa sedes fieret firma, deus filius sapiens, ut fieret artificialis, spiritus sanctus bonus, vt fieret bona\plain \f1\lang1033\fs24 . \endash  (192\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -193\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Sermo 4: \plain \f1\i\lang1033\fs24 Sequitur sermo de purificacione beate virginis\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [P]ostquam impleti sunt dies purgacionis eius (Lc 2,22). Solus hodie gaudeat omne genus humanum}}\plain \f1\i\lang1033\fs24 . Ratio: Quia nullus gradus pretermissus est \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 si enim mulieres\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 enixam aut menstruosam prohibemus intrare ecclesiam, eius penam ulterius in culpam; beate eciam communionis misterium mulier menstruosa in hiis diebus\plain \f1\lang1033\fs24 . \endash  193\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Parallelhss. und Lit.: (Sermo 1)\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs20 Ansbach, SB,{\field{\*\fldinst HYPERLINK "hida://5007[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat18  Ms. lat. 93}}\plain \f1\lang1033\fs20 , 319\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 . \endash  Freiburg, UB,{\field{\*\fldinst HYPERLINK "hida://5007[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat18  Hs. 282}}\plain \f1\lang1033\fs20 , 69\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 . \endash  W\u252 \'fcrzburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[2]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat18 M.ch.qu. 412}}\plain \f1\lang1033\fs20 , 142\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -142\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , vgl. \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium 4, S. 562, Nr. 170 (S80) mit Zuschreibung der Predigt an Peregrinus de Oppeln, Sermo in commemoratione omnium fidelium defunctorum. \endash  (Sermo 3) Antonius de Parma, In nativitate BMV, vgl. \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Repertorium 1, S. 302, Nr. 165 (S65).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

