\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 194\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -225\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Heinrich von Friemar}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Sermones de tempore}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 >F<elicitas est bonum ultimum et ideo optimum, sicut dicit aristoteles in primo ethicorum}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 . \plain \f1\i\lang1033\fs24 Ideo ego frater gotfridus de frimaria illud opusculum sermonum contraxi ad erudicionem iuuenum fratrum atque studencium\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 christus est enim temperancie via per humilitatem, que tibi erit eterna mansio per diuinitatem, que enim contueris dominum cum sanctis suis perhenniter in secula sedulorum\plain \f1\lang1033\fs24 . \endash  (225\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Schlussschrift: \plain \f1\i\lang1033\fs24 Expliciunt sermones seu collecciones compilate a fratre henrico de fremaria, doctore necnon professore sacre sancte theologie, confrater\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 fratrum ordinis Augustini in ciuitate Erfordiensi sub anno domini M\u176 \'b0 ccc\u176 \'b0 iv\u176 \'b0 in crastino Vdalrici confessoris\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Lit.: C. \plain \f1\scaps\lang1033\fs20 Stroick\plain \f1\lang1033\fs20 , Heinrich von Friemar. Leben, Werke, philosophisch-theologische Stellung in der Scholastik. Freiburg 1954 (Freiburger theologische Studien 68), S. 42 f. \endash  \plain \f1\scaps\lang1033\fs20 Zumkeller\plain \f1\lang1033\fs20 , Manuskripte, S. 158, Nr. 331.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

