\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Nota de circumcisione, quod christus propter multas causas uoluit circumcidi}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 nam christiani, qui deberent esse filii israel, deum per fidem et opera uirtuosa contemplantes semper in circumcisi corde, quia habent mentem uelatam malis cogitacionibus quasi a se amputare despiciunt, sed magis in ipsis. Habent complacenciam et postea in effectum producunt propria viciosa\plain \f1\lang1033\fs24 .}

