\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 Augustinus de laude caritatis\plain \f1\lang1033\fs24 <. >\plain \f1\i\lang1033\fs24 D\plain \f1\lang1033\fs24 <\plain \f1\i\lang1033\fs24 iuinarum scripturarum multiplicem habundantiam\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 oportet enim vt senilis sermo non solum sit grauis, sed etiam breuis\plain \f1\lang1033\fs24 .
