\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 330\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -334\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Nicolaus de Dinkelspuhel}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Sermo de eucharistia}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [E]Go sum panis vite (Io 6,41). \u8230 \'85 In priori sermone aggregatum ex fidelibus}}\plain \f1\i\lang1033\fs24 , ad invicem caritate connexis, ex ceteris causis ibi expressis vocauimus corpus christi misticum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 scilicet christus dominus de celo venit et est cibus omnes fideles se ad eum debite disponentes spiritualiter reficiens et facians et sanans, qui viuit etc\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs20 Madre\plain \f1\lang1033\fs20 , Nikolaus von Dinkelsb\u252 \'fchl, S. 246, diese Hs.: S. 248.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 334\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -344\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Ps.-Nicolaus de Dinkelspuhel}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Sermo de eucharistia}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 (334\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -342\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) Sermo: {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 [V]Enite ad me omnes qui laboratis \u8230 \'85 (Mt 11,28). \u8230 \'85 Dilectissimi in domino locuturus aliqua de venerando eucharistie sacramento}}\plain \f1\i\lang1033\fs24  et eius digna suscepcione\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 dictis septem modis aut sibi aliquo modo equiualentibus et \u8250 \'9bego reficiam uos\u8249 \'8b sacramentaliter et spiritualiter corpore meo\plain \f1\lang1033\fs24 . \endash  (342\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -343\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , Z. 15) Expositio secundum Thomam de Aquino:{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18  [D]E effectibus huius sacramenti est sciendum secundum Sanctum Thomam parte tertia}}\plain \f1\i\lang1033\fs24 , questione 79, articulo primo, quod effectus huius sacramenti primo et principaliter consideratur ex eo, quod in hoc sacramento continetur, quod est christus \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 sed tamen hoc sacramentum quantum est ex se habet vim conseruativam a peccato\plain \f1\lang1033\fs24 . \endash  (343\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , Z. 16-344\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Oraciones secundum Sanctum Thomam, quia dictum est de multis effectibus}}\plain \f1\i\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 \u8250 \'9bEgo vero quandoque, sicut possum, preparo me ad sumendum hoc sacramentum}}\plain \f1\i\lang1033\fs24  et tantum post sumpcionem eius nihil spiritualis solacii nec dulcedinis sentio\u8249 \'8b. Ad hoc respondet sanctus Thomas in tractatu suo de corpore christi dicens, quod cibus ille est hominis medicinam \plain \f1\lang1033\fs24 \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 de quibus hic dictum est et cum quibus ad hoc sacramentum debes venire uel salubrius reficiaris, quod concedere dignetur esca angelorum et cibus sanctarum animarum Ihesus christus, dominus noster, qui cum patre\plain \f1\lang1033\fs24  \u8230 \'85 \plain \f1\i\lang1033\fs24 Amen\plain \f1\lang1033\fs24 . \endash  (344\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs26 )\plain \f1\lang1033\fs24  Schlussschrift: >\plain \f1\i\lang1033\fs24 Explicit tractatus de corpore christi Magistri Nicolai de dinckelsp\u252 \'fchel\plain \f1\lang1033\fs24 <.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Zum \plain \f1\i\lang1033\fs20 sermo\plain \f1\lang1033\fs20  vgl. \plain \f1\scaps\lang1033\fs20 Madre\plain \f1\lang1033\fs20 , Nikolaus von Dinkelsb\u252 \'fchl, S. 318 (Textschluss der Predigt abweichend). \endash  Die \plain \f1\i\lang1033\fs20 expositio\plain \f1\lang1033\fs20  ist eine \u252 \'fcberarbeitete und gek\u252 \'fcrzte Fassung von Thomas, III\plain \f1\super\lang1033\fs20 a\plain \f1\lang1033\fs20  Sum. theol., qu. 79. art. 1-6. \endash  Der nachfolgende Abschnitt wird mit einem Zitat eingeleitet aus: Ps.-Thomas de Aquino, De venerabili sacramento altaris, c. 22. Druck: Divi Thomae Aquinatis opuscula. \plain \f1\lang1033\fs20\cf1 De duobus praeceptis charitatis et decem legis praeceptis ejusdemque de venerabili sacramento altaris. Ed. C. \plain \f1\scaps\lang1033\fs20\cf1 Martin\plain \f1\lang1033\fs20\cf1 . K\u246 \'f6ln, Bonn, Br\u252 \'fcssel 1852 (Bibliotheca mystica et ascetica 9), S. 261 f.\plain \f1\lang1033\fs20  \plain \f1\lang1033\fs20\cf1 \endash  \plain \f1\lang1033\fs20 Die Schlussschrift auf 344\plain \f1\super\lang1033\fs20 rb\plain \f1\lang1033\fs20  subsumiert die Werke ab 305\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20  unter dem Namen des Nicolaus de Dinkelspuhel.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Verdana;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 344\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -344\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Notae variae zur Transubstantiation}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 (\plain \f1\lang1033\fs24 1\plain \f1\i\lang1033\fs24 ) Et est {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 circa hoc bene notandum, quod licet in aliquibus rubricis dicatur illud vinum in calice sanctificari}}\plain \f1\i\lang1033\fs24 , hoc tantum non est sic intelligendum, quod vinum illud consecretur et transsubstancietur in sanguine christo\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 cum in calice sit tunc solum purum vinum non consecratum, propter quod non fit ibi commixtio specierum corpus christi cum speciebus sangwinis.\plain \f1\lang1033\fs24  \endash  (2) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Dubitatur, quare calix et non hostia cooperitur. Quadruplex ratio: Primo propter periculum}}\plain \f1\i\lang1033\fs24 , quia sanguis facilius potest recipere in medicinam quam hostia\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 quarto: sanguis in calice cooperto reuertat christi corpus in sindone inuolutum, hostia uero corpus non inuolutum\plain \f1\lang1033\fs24 . \endash  (3) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Dubium, utrum accidencia sacramentalia habeant potenciam conuertendi alia in sacramentum}}\plain \f1\i\lang1033\fs24 , ut si vino in calice consecrato apponatur vinum uel aqua, an ista conuertat in sanguinem. Benedicet Bonauentura, quod species sacramentales nullomodo habent uirtutem conuertendi aliam substantiam quamcumque in sacramentum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 sed si aliquid debet hic in ipsum conuerti, oportet quod hoc fiat per transsubstanciacionem et nouam consecracionem. Hec de illo\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

