\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -29\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Nicolaus de Dinkelspuhel}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Sermo Dominica prima in Quadragesima, sermo 2}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 >\plain \f1\i\lang1033\fs24 E\plain \f1\lang1033\fs24 <\plain \f1\i\lang1033\fs24 St communiter aliquid dicendum et primo de ieiunio. Rogemus ergo Mariam virginem, ut nobis gratiam ad hoc necessariam impetret\plain \f1\lang1033\fs24  \u8230 \'85 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Totus sermo stabit in aliquot questionibus, quarum prima est}}\plain \f1\i\lang1033\fs24 : Ad quid valeat jeiunium et quare fuerit ab ecclesia institutum\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 que animam deo gratam reddunt et dignam premio sempiterno, quod nobis misericorditer largiri dignetur ihesus christus dominus, qui cum patre et spiritu sancto viuit et regnat vunus deus benedictus. Amen\plain \f1\lang1033\fs24 . \endash  Schlussschrift: >\plain \f1\i\lang1033\fs24 Explicit tractatus magistri nicolay de dinckelspuchel de jeiunio\plain \f1\lang1033\fs24 <. \endash  29\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Die Predigt stammt aus dem Zyklus \plain \f1\i\lang1033\fs20 Sermones dominicales. Pars hiemalis\plain \f1\lang1033\fs20 . \endash  Lit.: \plain \f1\scaps\lang1033\fs20 Madre\plain \f1\lang1033\fs20 , Nikolaus von Dinkelsb\u252 \'fchl, S. 138 f., Nr. 20, S. 157 (diese Hs.).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

