\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 94\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -127\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Ambrosius Mediolanensis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 De virginibus}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  leer. \endash  (94\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -102\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Incipit liber primvs beati Ambrosii de virginibvs\plain \f1\lang1033\fs24 <. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 >Si ivxta celestis sententiam veritatis< uerbi totius quodcumque ociosum fuerimus loquuti}}\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 habetis, puelle, deuotionis premium, parentes, cauete offensionis exemplum\plain \f1\lang1033\fs24 . >\plain \f1\i\lang1033\fs24 Explicit liber I\plain \f1\lang1033\fs24 <. \endash  (102\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -107\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Incipit secvundvs\plain \f1\lang1033\fs24 <. >\plain \f1\i\lang1033\fs24 Svperiore libro quantvm virginitatis\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 munus sit, uoluimus, non enim potuimus explicare\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 uerum etiam bonorum propugnacula struat tuta meritorum.\plain \f1\lang1033\fs24  >\plain \f1\i\lang1033\fs24 Explicit liber II\plain \f1\lang1033\fs24 <. \endash  (107\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -112\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Incipit liber tercivs\plain \f1\lang1033\fs24 <. >\plain \f1\i\lang1033\fs24 Quoniam que habuimvs digessimus svperioribvs\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 libris duobus, tempus est, soror sancta, ea que mecum conferre soles, beate memorie Liberii praecepta reuoluere\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 denique cum cetera penarum genera uicisset, gladium quem querebat, inuenit.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Vgl. \u179 \'b3CPL 145. \endash  Druck: PL 16, 187A-232A. \endash \plain \f1\lang1033\fs20\cf1  S. \plain \f1\lang1033\fs20 Ambrosii Mediolanensis episcopi d\plain \f1\lang1033\fs20\cf1 e virginibus libri tres. Ed. I. \plain \f1\scaps\lang1033\fs20\cf1 Cazzaniga\plain \f1\lang1033\fs20\cf1 . Turin 1948 \plain \f1\lang1033\fs18\cf1 (\plain \f1\lang1033\fs20\cf1 Corpus scriptorum Latinorum Paravianum), S. 1-76. \endash  Ambrosius Mediolanensis, \plain \f1\lang1033\fs20 De virginibus. De viduis = Verginit\u224 \'e0 e Vedovanza. Introduzione, traduzione, note e indici di F. \plain \f1\scaps\lang1033\fs20 Gori\plain \f1\lang1033\fs20 . Textum post Egnatium \plain \f1\scaps\lang1033\fs20 Cazzaniga\plain \f1\lang1033\fs20 . Mailand 1989 (\plain \f1\lang1033\fs20\cf1 Sancti Ambrosii episcopi Mediolanensis opera \plain \f1\lang1033\fs20 14,1 = Opere morali 2,1), S. 100-240. \endash  F. \plain \f1\scaps\lang1033\fs20 Gori\plain \f1\lang1033\fs20 , Emendazioni Ambrosiane. III. Gli scritti sulla verginit\u224 \'e0, in: Orpheus, N. S. 10 (1989), S. 80-100, ebd. S. 80-89. \endash \plain \f1\lang1033\fs20\cf1  Vgl. zur Handschrift und ihrer Stellung in der handschriftlichen \u220 \'dcberlieferung die Ed., Turin 1948, S. [V]f. (Sigle M, mit falscher Provenienzzuweisung), S. Xf. (M geh\u246 \'f6rt zum deutsch-italienischen \u220 \'dcberlieferungszweig), S. XVII, Nr. 6 (M geh\u246 \'f6rt zur Handschriftenklasse k, mit Interpolationen aus der Handschriftenklasse h), S. XXXII. \endash  Zu weiteren Textzeugen vgl. \plain \f1\lang1033\fs20 G. \plain \f1\scaps\lang1033\fs20 Cremas\plain \f1\scaps\lang1033\fs20 chi\plain \f1\scaps\lang1033\fs20 ,\plain \f1\lang1033\fs20  Il \plain \f1\i\lang1033\fs20 De virginibus\plain \f1\lang1033\fs20  di S. Ambrogio in un codice ignoto del sec. XII, in: Atti dell\rquote Istituto Veneto di scienze, lettere ed arti 110 (1951/1952), S. 44-55.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

