\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 >Nobile apud ueteres Salomonis illud fertur fuisse iudicium}}\plain \f1\i\lang1033\fs24 , cum\plain \f1\lang1033\fs24 < \plain \f1\i\lang1033\fs24 a duabus litigantibus mulieribus interpellatus esset\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 in illo, quia mundum descripsit, in isto, quia mundum ignorauit\plain \f1\lang1033\fs24 . \endash  127\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
