\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20\cf1 Holzdeckeleinband mit blauem Lederbezug. Hinterer Deckel durch Pappe ersetzt (Restaurierung Oktober 1923). Streicheisenmuster. Ehemals je f\u252 \'fcnf Buckel auf den Deckeln, abgenommen. Im unteren Schnitt Titel. \plain \f1\i\lang1033\fs20\cf1 S\plain \f1\lang1033\fs20\cf1 [ermones]\plain \f1\i\lang1033\fs20\cf1 mgri Tho\plain \f1\lang1033\fs20\cf1 [mae] \plain \f1\i\lang1033\fs20\cf1 de haselbach\plain \f1\lang1033\fs20\cf1 . Auf dem R\u252 \'fccken Papierschildchen mit Signatur \plain \f1\i\lang1033\fs20\cf1 91\plain \f1\lang1033\fs20\cf1 . }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20\cf1 Vorderer und hinterer Spiegel Papier. Zeigt 2-spaltigen theologischen Text, 14. Jh. aus ein und derselben Hs. Wegen fehlender Rubriken nicht n\u228 \'e4her identifizierbar. Breite Pergamentf\u228 \'e4lze um die erste und die letzte Lage: Zwei zusammengeh\u246 \'f6rige Spalten aus dem Blatt eines liturgischen Psalteriums (Pss. zur Prim: 24. 25. 53. 117. 118), {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17\cf1 gotische Minuskel}}\plain \f1\lang1033\fs20\cf1 , {\field{\*\fldinst HYPERLINK "hida://5060[1].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17\cf1 13. Jh}}\plain \f1\lang1033\fs20\cf1 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Verdana;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red157\green185\blue235;\red157\green185\blue235;}

