\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 5\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Concordantia prophetarum cum symbolo apostolico}}
\par \pard\fi0\li0\tx1335\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\tx1260\tx3885\tx5430\tx8070\ql\ri0\sb0\sa0\itap0 (Propheten des AT) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Jeremias: Patrem inuocabitis qui terram fecit et condidit celos}}\plain \f1\i\lang1033\fs24 . Deus pater omnipotens\plain \f1\lang1033\fs24 . (Symbolum apostolicum) \plain \f1\i\lang1033\fs24 Credo in deum patrem omnipotentem, creatorem celi et terre. Petrus apostolus\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 (Propheten des AT) \plain \f1\i\lang1033\fs24 Ezechiel: Euigilabunt omnes alii ad vitam, alii ad opprobrium \plain \f1\lang1033\fs24 (Dn 12,2). \plain \f1\i\lang1033\fs24 Vita eterna in celo\plain \f1\lang1033\fs24 . (Symbolum apostolicum) \plain \f1\i\lang1033\fs24 Et vitam eternam. Amen. Mathias\plain \f1\lang1033\fs24 . \endash  \plain \f1\i\lang1033\fs24 Vnde versus: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Nascitur, abluitur, moritur, descendit ad yma}}\plain \f1\lang1033\fs24  | \plain \f1\i\lang1033\fs24 Surgit et ascendit, veniens discernere cuncta\plain \f1\lang1033\fs24 . (\plain \f1\scaps\lang1033\fs24 Walther\plain \f1\lang1033\fs24 , Initia, Nr. 11568).
\par \pard\fi0\li0\tx1335\ql\ri0\sb0\sa0\itap0 
