\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 133\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -137\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Ps.-Aurelius Augustinus}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18 Speculum peccatorum}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u220 \'dcberschrift von der Nachtragshand: \plain \f1\i\lang1033\fs24 Incipit Speculum peccatorum\plain \f1\lang1033\fs24 . \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 >Q<VOniam, karissimi, in via huius vite fugientis}}\plain \f1\i\lang1033\fs24  dies nostre salutis sicut vmbra pretereunt\plain \f1\lang1033\fs24  \u8230 \'85 \endash  \u8230 \'85 \plain \f1\i\lang1033\fs24 et cum domino ihesu christo vitam eternam possideas, qui tibi concedat iste, qui est benedictus in secula seculorum. Amen\plain \f1\lang1033\fs24 . \endash  Schlussschrift: \plain \f1\i\lang1033\fs24 Explicit Speculum peccatorum. \u183 \'b7ff\u183 \'b7iv\u183 \'b7\plain \f1\lang1033\fs24  (= finivi) \plain \f1\i\lang1033\fs24 42\u176 \'b0\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Zu Druck und Lit. vgl. 3786, 19\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 -22\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 . Diese Hs. genannt: \plain \f1\scaps\lang1033\fs20 Lambert\plain \f1\lang1033\fs20 , Bibliotheca Hieronymiana manuscripta 3B, Nr. 616, S. 490-496, ebd. S. 494. \endash  \plain \f1\scaps\lang1033\fs20 Kurz\plain \f1\lang1033\fs20 , Hsl. \u220 \'dcberlieferung V/1, S. 227, Nr. 78, Bd. V/2, S. 296. \endash  \plain \f1\scaps\lang1033\fs20 Bloomfield\plain \f1\lang1033\fs20 , Incipits, Nr. 4918.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

