\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Von der Nachtragshand: \plain \f1\i\lang1033\fs24 Consequenter sequitur tractatus, qui dicitur de viciis palleantibus\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 se sub speciebus virtutum\plain \f1\lang1033\fs24 . \endash  (159\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -159\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Prolog: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 >}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 E}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 <}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 st via, que videtur hominibus recta, nouissima autem eius ducunt ad mortem}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 (Prv 14,12). }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Quia secundum Gregorium tricesimoquarto}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18  (!) }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 moralium multa sunt vicia}}\plain \f1\i\lang1033\fs24 , que sub specie virtutum se occultant\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 que sunt cuiuslibet spiritus superbie singulariter curancia\plain \f1\lang1033\fs24  (!). \endash  (159\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -169\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat18 Circa primum est sciendum, quod superbia quandoque sub triplici virtutum specie se occultat}}\plain \f1\lang1033\fs24  ... \endash  ... \plain \f1\i\lang1033\fs24 faciliter terciam lasciuiam a cordis hospicio poterimus exstirpare, quod nobis prestare dignetur\plain \f1\lang1033\fs24 . \endash  Schlussschrift: \plain \f1\i\lang1033\fs24 Explicit tractatus de viciis palleantibus\plain \f1\lang1033\fs24  (!) \plain \f1\i\lang1033\fs24 sub speciebus virtutum etc\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Druck und Lit.: Henrici de Frimaria O.S.A. Tractatus ascetico-mystici. Ed. A. \plain \f1\scaps\lang1033\fs20 Zumkeller\plain \f1\lang1033\fs20 . Bd. 2: Tractatum de septem gradibus amoris et Tractatum de occultatione vitiorum sub specie virtutum. Rom 1992 (Corpus scriptorum Augustinianorum 3,2), S. 19-47, S. 21 (diese Hs.), S. 93-144 (Edition). \endash  \plain \f1\scaps\lang1033\fs20 Zumkeller\plain \f1\lang1033\fs20 , Manuskripte, Nr. 316, S. 138-140 (diese Hs.). \endash  \plain \f1\scaps\lang1033\fs20 Bloomfield\plain \f1\lang1033\fs20 , Incipits, Nr. 1982 (ohne diese Hs.).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

